using Captovix;
using Captovix.Licensing;
using System.Security.Cryptography;
int count=0;void Check(bool ok,string text){if(!ok)throw new Exception(text);count++;Console.WriteLine("PASS: "+text);}void Reject(Action a,string text){try{a();}catch(ArgumentException){Check(true,text);return;}catch(System.IO.InvalidDataException){Check(true,text);return;}throw new Exception("Accepted invalid: "+text);}
const int w=640,h=360;var pixels=Enumerable.Repeat((byte)255,w*h*4).ToArray();
void Fill(PixelRect b,byte r,byte g,byte blue){for(int y=b.Y;y<b.Bottom;y++)for(int x=b.X;x<b.Right;x++){int n=(y*w+x)*4;pixels[n]=blue;pixels[n+1]=g;pixels[n+2]=r;}}
Fill(new(180,100,240,38),180,180,180);Fill(new(182,102,236,34),255,255,255);Fill(new(180,160,120,38),40,110,220);
var before=pixels.ToArray();var lines=new OcrTextLine[]{new(new(30,108,110,20),"Họ và tên",.97f),new(new(196,110,130,18),"Nhập họ tên",.93f),new(new(202,170,70,18),"Tìm kiếm",.96f),new(new(202,170,70,18),"Tìm kiếm",.5f),new(new(30,34,220,30),"Quản lý sinh viên",.98f),new(new(30,230,140,18),"Chữ chưa chắc",.45f)};
var result=ElementScan.Analyze(pixels,w,h,new(50,60,w,h),lines);Check(pixels.SequenceEqual(before),"Scanning does not mutate source pixels");Check(result.Elements.All(x=>!x.Include),"All proposals default to unchecked; scanning cannot apply them");
var button=result.Elements.Single(x=>x.Kind==MockupKind.Button&&x.Text.Contains("Tìm kiếm"));Check(button.Text=="Tìm kiếm","OCR merges into button without duplicate line/object");var input=result.Elements.Single(x=>x.Kind==MockupKind.Input&&x.Text.Contains("Nhập họ tên"));Check(input.Bounds.X>=228&&input.Bounds.Y>=158,"Source offset preserved for input detection");var label=result.Elements.Single(x=>x.Text=="Họ và tên");Check(label.LabelForId==input.Id,"Nearby label is paired with input control");Check(result.Elements.Any(x=>x.Kind==MockupKind.Title&&x.Text=="Quản lý sinh viên"),"Larger OCR line is proposed as title");Check(result.Elements.Single(x=>x.Text=="Chữ chưa chắc").Uncertain,"Low-confidence OCR is explicitly uncertain");Check(input.Uncertain,"Input geometry remains review-required even with clear OCR");
Check(!result.Elements.Any(a=>result.Elements.Any(b=>a.Id!=b.Id&&a.Kind==b.Kind&&ElementScan.Overlap(a.Bounds,b.Bounds)>.8)),"Duplicate candidate bounds removed");
var blank=Enumerable.Repeat((byte)255,w*h*4).ToArray();Check(ElementScan.Analyze(blank,w,h,new(0,0,w,h),[]).Elements.Count==0,"Flat full background is not misclassified as one editable control");
var document=new EditorDocument{OriginalWidth=800,OriginalHeight=500,SourceHash="original"};var session=new EditorSession(document);string initial=document.Serialize();Reject(()=>ElementScan.Prepare(document,result.Elements,new(50,60,w,h)),"Apply requires explicit selected elements");Check(!session.CanUndo&&document.Serialize()==initial,"Review-only proposals do not change document/history");
label.Include=input.Include=button.Include=true;var prepared=ElementScan.Prepare(document,result.Elements,new(50,60,w,h));Check(prepared.Count==5&&prepared.All(x=>x.Mockup!.FromScan),"Approved controls split into grouped editable text and shape objects");Check(prepared.Single(x=>x.Text=="Họ và tên").Mockup!.LabelForId==prepared.Single(x=>x.Mockup!.Type==MockupKind.Input).Id,"Approved label/control relationship maps to new object IDs");session.Change(d=>ElementScan.Apply(d,result.Elements,new(50,60,w,h)));Check(session.Document.Version==19&&session.Document.Annotations.Count==5,"M2 writes protected schema19 in a single edit");string applied=session.Document.Serialize();session.Undo();Check(session.Document.Serialize()==initial,"Undo restores exact pre-scan document");session.Redo();Check(session.Document.Serialize()==applied,"Redo restores exact approved objects and links");var saved=EditorDocument.Deserialize(applied);saved.Validate(800,500,"original");Check(saved.Annotations.Any(x=>x.Mockup!.Type==MockupKind.Input)&&saved.SourceHash=="original"&&saved.PixelBasePng==null,"Save/reopen retains input, relationship and original source");
var controlShape=prepared.Single(x=>x.Mockup!.Type==MockupKind.Button);var controlText=prepared.Single(x=>x.Text=="Tìm kiếm");Check(controlShape.Text==""&&controlText.Mockup!.Type==MockupKind.Label&&controlShape.GroupId==controlText.GroupId&&controlShape.GroupId!=null,"Control and text are independent members of one group");
Check(!controlText.Mockup!.EraseOriginal&&controlText.Mockup.Background==controlShape.FillColor,"Text child uses control fill and cannot erase original source independently");
Check(prepared.All(a=>a.Stroke>=1),"Borderless output retains valid stored stroke width");
var styled=new ScanElement{Bounds=new(20,20,160,40),Kind=MockupKind.Button,Include=true,BorderColor="#8492A6",BorderWidth=2,Radius=9,FontFamily="Tahoma",FontSize=19,Text="Save"};var style=ElementScan.Prepare(document,[styled],new(0,0,800,500)).Single();Check(style.Color=="#8492A6"&&style.Stroke==2&&style.CornerRadius==9&&style.FontFamily=="Tahoma"&&style.FontSize==19,"Reviewed font, border color, width and corner radius survive materialization");
var large=Enumerable.Repeat((byte)255,1600*1000*4).ToArray();long allocated=GC.GetAllocatedBytesForCurrentThread();_=ElementScan.Sample(large,1600,1000,new(10,10,1500,900));allocated=GC.GetAllocatedBytesForCurrentThread()-allocated;Check(allocated<1_000_000,"Large control color sampling allocates under 1MB instead of a full raster copy");Console.WriteLine("SAMPLE_ALLOCATED_BYTES="+allocated);
var reuse=ElementScan.Analyze(pixels,w,h,new(50,60,w,h),lines,default,ElementScan.Analyze(pixels,w,h,new(50,60,w,h),[]).Elements);Check(reuse.Elements.Count==result.Elements.Count,"OCR merge reuses visual analysis without changing proposal count");
var nested=new ScanElement{Bounds=new(0,0,500,300),Kind=MockupKind.Block,Include=true};var nestedPrepared=ElementScan.Prepare(document,[nested,styled],new(0,0,800,500));var nestedDoc=new EditorDocument{OriginalWidth=800,OriginalHeight=500,Annotations=nestedPrepared};nestedDoc.Validate(800,500,"");Check(nestedPrepared.All(a=>GroupLayout.Chain(a).Length>0),"Selected container and contained controls receive consistent parent grouping");
var repeated=new ScanElement{Bounds=button.Bounds,Kind=button.Kind,Include=true};Reject(()=>ElementScan.Prepare(document,[button,repeated],new(50,60,w,h)),"Review cannot apply duplicate selected frames");
var ids=session.Document.Annotations.Select(x=>x.Id).ToArray();var packet=AnnotationClipboard.Copy(session.Document,ids);var target=new EditorDocument{OriginalWidth=800,OriginalHeight=500};AnnotationClipboard.Paste(target,packet,10,a=>new(a.Left,a.Top,a.Width,a.Height));var pastedLabel=target.Annotations.Single(x=>x.Text=="Họ và tên");Check(pastedLabel.Mockup!.LabelForId==target.Annotations.Single(x=>x.Mockup!.Type==MockupKind.Input).Id&&target.Annotations.All(x=>!x.Mockup!.EraseOriginal),"Copy/paste remaps label/control IDs without source erasure");
var duplicated=session.Document.Snapshot();var fresh=AnnotationEditing.Duplicate(duplicated,ids,a=>new(a.Left,a.Top,a.Width,a.Height));Check(duplicated.Annotations.Single(x=>fresh.Contains(x.Id)&&x.Text=="Họ và tên").Mockup!.LabelForId==duplicated.Annotations.Single(x=>fresh.Contains(x.Id)&&x.Mockup!.Type==MockupKind.Input).Id,"Duplicate keeps relationship within duplicate set");
button.Bounds=button.Bounds with{X=799};string checkpoint=session.Document.Serialize();Reject(()=>session.Change(d=>ElementScan.Apply(d,result.Elements,new(50,60,w,h))),"Invalid edited bounds rejected atomically");Check(session.Document.Serialize()==checkpoint,"Failed apply keeps prior document intact");button.Bounds=button.Bounds with{X=230};
using(var cancel=new CancellationTokenSource()){cancel.Cancel();try{ElementScan.Analyze(blank,w,h,new(0,0,w,h),[],cancel.Token);throw new Exception("Cancellation ignored");}catch(OperationCanceledException){Check(true,"Image analysis supports cancellation");}}
var many=Enumerable.Range(0,500).Select(i=>new OcrTextLine(new(i%20*32,i/20*14,20,8),"Nhãn"+i,.9f)).ToArray();var limited=ElementScan.Analyze(blank,w,h,new(0,0,w,h),many);Check(limited.Truncated&&limited.Elements.Count==200&&limited.Warning.Length>0,"Large scans are capped with an explicit truncation warning");
Reject(()=>ElementScan.Analyze(new byte[4],w,h,new(0,0,w,h),[]),"Malformed raster rejected");
var now=DateTimeOffset.Parse("2026-11-04T05:00:00Z");var end=now.AddDays(12).AddHours(2);var claims=new Claims(1,Protocol.Product,"test","license","activation","device","hash","trial","active",now,now.AddHours(48),end);
var trial=LicensePresentation.Create(claims,end,now,true);Check(trial.TrialUsed&&!trial.CanStartTrial&&!trial.Perpetual&&trial.Heading=="Dùng thử 30 ngày","Trial status suppresses a second trial and keeps upgrade available");Check(trial.Details.Contains("13 ngày")&&trial.Details.Contains(end.AddDays(-30).ToLocalTime().ToString("dd/MM/yyyy HH:mm:ss")),"Trial uses original start timestamp and rounded remaining days");var expired=LicensePresentation.Create(claims,end,now.AddDays(20),false);Check(expired.Details.Contains("0 ngày")&&!expired.CanStartTrial,"Expired trial never resets or permits restart");var permanent=claims with{Kind="perpetual",TrialUntil=null,ActivatedAt=now.AddDays(-50)};var full=LicensePresentation.Create(permanent,end,now,true);Check(full.Perpetual&&full.Heading.Contains("✓")&&!full.CanStartTrial,"Perpetual status has check mark and no trial offer");Check(full.Details.Contains(permanent.ActivatedAt!.Value.ToLocalTime().ToString("dd/MM/yyyy HH:mm:ss")),"Perpetual activation date comes from activation metadata");Check(LicensePresentation.Create(permanent with{IssuedAt=now.AddDays(1)},end,now.AddDays(1),true).Details==full.Details,"Refresh cannot change the displayed activation timestamp");Check(LicensePresentation.Create(permanent with{ActivatedAt=null},null,now,true).Details.Contains("chứng nhận cũ"),"Old certificate never fabricates an activation date from refresh time");Check(!LicensePresentation.Create(null,null,now,false).Registered&&LicensePresentation.Create(null,null,now,false).CanStartTrial,"Fresh installation can choose trial/key");Check(!LicensePresentation.Create(permanent,null,now,false).Heading.Contains("✓"),"Unverified perpetual lease does not claim active entitlement");
Console.WriteLine(count+" element scan/review/license presentation checks passed.");
